function mapToDittoProtocolMsg(headers, textPayload, bytePayload, contentType) {
  var payload = JSON.parse(textPayload);
  var deviceUuid = payload.device_uuid;
  var thingId = 'org.c2dta:' + deviceUuid;
  var value = {
    heartbeat: {
      properties: {
        bpm: payload.heartbeat_bpm
      }
    },
    geolocation: {
      properties: {
        latitude: payload.geolocation.lat,
        longitude: payload.geolocation.lon
      }
    },
    timestamp: {
      properties: {
        value: payload.timestamp
      }
    }
  };
  return Ditto.buildDittoProtocolMsg(
    'org.c2dta',
    deviceUuid,
    'things',
    'twin',
    'commands',
    'merge',
    '/features',
    headers,
    value
  );
}
